const META = {"volT":[98,146],"magT":[30,73],"start":1783486800,"end":1785906000,"n":2688};

// row: [ts, dow(0=Mon), hr, q, open, maxUp, maxDn, avgMinRng, lastMinRng, d0..d14]
const S = (() => {
  const out = RAW.map((r, i) => {
    const d = r.slice(9);
    const f = d[14];
    let flips = 0, prev = 0;
    for (let k = 0; k < 15; k++) {
      const sg = d[k] > 0 ? 1 : d[k] < 0 ? -1 : prev;
      if (prev !== 0 && sg !== 0 && sg !== prev) flips++;
      if (sg !== 0) prev = sg;
    }
    return {
      i, ts: r[0], dow: r[1], hr: r[2], q: r[3], o: r[4],
      mU: r[5], mD: r[6], aMR: r[7], lMR: r[8], d, f,
      dir: f > 0 ? "U" : f < 0 ? "D" : "F",
      rng: r[5] - r[6], flips,
    };
  });
  for (let i = 0; i < out.length; i++) {
    const s = out[i];
    s.pat = [];
    for (let j = 5; j >= 1; j--) s.pat.push(i - j >= 0 ? out[i - j].dir : null); // pat[4] = most recent
    s.prevAbs = i > 0 ? Math.abs(out[i - 1].f) : null;
    s.drift = [];
    for (let N = 1; N <= 5; N++) s.drift.push(i - N >= 0 ? Math.round(s.o - out[i - N].o) : null);
    if (i >= 8) {
      let t = 0;
      for (let j = i - 8; j < i; j++) t += out[j].rng;
      const m = t / 8;
      s.vol = m < META.volT[0] ? "L" : m < META.volT[1] ? "M" : "H";
    } else s.vol = null;
  }
  return out;
})();

// ---------------- helpers ----------------
const DOWS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const BLOCKS = [
  { l: "12–4a", h: [0, 3] }, { l: "4–8a", h: [4, 7] }, { l: "8a–12p", h: [8, 11] },
  { l: "12–4p", h: [12, 15] }, { l: "4–8p", h: [16, 19] }, { l: "8p–12a", h: [20, 23] },
];
const LEAD_BUCKETS = [
  { l: "$1–10", lo: 1, hi: 10 }, { l: "$10–25", lo: 10, hi: 25 }, { l: "$25–50", lo: 25, hi: 50 },
  { l: "$50–100", lo: 50, hi: 100 }, { l: "$100+", lo: 100, hi: 1e9 },
];
const CHECKPOINTS = [5, 8, 10, 12, 14];

const wilson = (k, n, z = 1.645) => {
  if (!n) return [0, 1];
  const p = k / n, z2 = z * z;
  const den = 1 + z2 / n, c = p + z2 / (2 * n), m = z * Math.sqrt((p * (1 - p) + z2 / (4 * n)) / n);
  return [Math.max(0, (c - m) / den), Math.min(1, (c + m) / den)];
};
const median = (a) => {
  if (!a.length) return null;
  const b = [...a].sort((x, y) => x - y), m = b.length >> 1;
  return b.length % 2 ? b[m] : (b[m - 1] + b[m]) / 2;
};
const mean = (a) => (a.length ? a.reduce((x, y) => x + y, 0) / a.length : null);
const fmt$ = (v, sign) => (v == null ? "—" : `${sign && v > 0 ? "+" : v < 0 ? "−" : sign ? "±" : ""}$${Math.abs(Math.round(v))}`);
const fmtP = (p) => (p == null ? "—" : `${Math.round(p * 100)}%`);
const magBucket = (v) => (v == null ? null : v < META.magT[0] ? "S" : v < META.magT[1] ? "M" : "B");
const hourLabel = (h) => `${((h + 11) % 12) + 1}${h < 12 ? "a" : "p"}`;

const nTone = (n) => (n >= 100 ? "text-zinc-400" : n >= 30 ? "text-amber-400" : "text-red-400");
const holdTone = (p) =>
  p == null ? "text-zinc-600" : p >= 0.85 ? "text-emerald-400" : p >= 0.7 ? "text-emerald-600" : p >= 0.55 ? "text-zinc-300" : "text-red-400";

// ---------------- small building blocks ----------------
const Chip = ({ on, tone, children, ...p }) => (
  <button
    {...p}
    className={`px-2.5 py-1.5 rounded-md border text-xs font-mono transition-colors select-none ${
      on
        ? tone === "U"
          ? "bg-emerald-500/15 border-emerald-500/60 text-emerald-300"
          : tone === "D"
          ? "bg-red-500/15 border-red-500/60 text-red-300"
          : "bg-zinc-100 border-zinc-100 text-zinc-900"
        : "bg-zinc-900 border-zinc-800 text-zinc-400 hover:border-zinc-600"
    }`}
  >
    {children}
  </button>
);

const Eyebrow = ({ children, right }) => (
  <div className="flex items-baseline justify-between mb-2">
    <div className="text-[10px] uppercase tracking-widest text-zinc-500 font-mono">{children}</div>
    {right ? <div className="text-[10px] font-mono text-zinc-600">{right}</div> : null}
  </div>
);

const Card = ({ children, className = "" }) => (
  <div className={`bg-zinc-900/60 border border-zinc-800 rounded-lg p-3.5 ${className}`}>{children}</div>
);

// ---------------- clock ----------------
function useCT() {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  return useMemo(() => {
    const p = new Intl.DateTimeFormat("en-US", {
      timeZone: "America/Chicago", hour12: false, weekday: "short",
      hour: "2-digit", minute: "2-digit", second: "2-digit",
    }).formatToParts(new Date(now));
    const g = (t) => p.find((x) => x.type === t)?.value;
    const hr = +g("hour") % 24, mi = +g("minute"), se = +g("second");
    const dowMap = { Mon: 0, Tue: 1, Wed: 2, Thu: 3, Fri: 4, Sat: 5, Sun: 6 };
    const dow = dowMap[g("weekday")] ?? 0;
    const mis = mi % 15; // minute index within session
    const secLeft = (14 - mis) * 60 + (60 - se);
    const startMin = mi - mis;
    const wl = (h, m) => `${((h + 11) % 12) + 1}:${String(m).padStart(2, "0")}`;
    const endH = startMin === 45 ? (hr + 1) % 24 : hr;
    const window = `${wl(hr, startMin)}–${wl(endH, (startMin + 15) % 60)}${endH < 12 ? "a" : "p"}`;
    return { hr, mi, se, dow, mis, secLeft, window, clock: `${g("hour")}:${g("minute")}:${g("second")}` };
  }, [now]);
}

// ---------------- app ----------------
const FRESH = {
  days: [], hourMode: "all", block: 0, hour: 12, q: null,
  pat: [null, null, null, null, null], vol: null, mag: null,
  minute: 0, sign: 1, magIn: "", tolMode: "auto", follow: false,
  lookN: 3, pxStart: "", pxNow: "",
};

export default function App() {
  const ct = useCT();
  const [f, setF] = useState(FRESH);
  const up = (patch) => setF((x) => ({ ...x, ...patch }));

  useEffect(() => {
    if (!f.follow || ct.mis === f.minute) return;
    setF((x) => ({ ...x, minute: ct.mis, ...(ct.mis < x.minute ? { magIn: "" } : {}) }));
  }, [ct.mis, f.follow, f.minute]);

  const delta = f.magIn !== "" && isFinite(+f.magIn) ? f.sign * Math.abs(+f.magIn) : null;
  const live = f.minute >= 1 && delta != null;
  const tol =
    delta == null ? 0
      : f.tolMode === "tight" ? Math.max(5, 0.2 * Math.abs(delta))
      : f.tolMode === "wide" ? Math.max(15, 0.6 * Math.abs(delta))
      : Math.max(8, 0.35 * Math.abs(delta));

  const num = (t) => (t !== "" && isFinite(+t) ? +t : null);
  const pxS = num(f.pxStart), pxN = num(f.pxNow);
  const net = pxS != null && pxN != null ? Math.round(pxN - pxS) : null;
  const driftOn = net != null;
  const tolD = !driftOn ? 0
    : f.tolMode === "tight" ? Math.max(8, 0.2 * Math.abs(net))
    : f.tolMode === "wide" ? Math.max(20, 0.6 * Math.abs(net))
    : Math.max(12, 0.35 * Math.abs(net));

  // ---- filter passes ----
  const passDay = (s) => !f.days.length || f.days.includes(s.dow);
  const passHour = (s) =>
    f.hourMode === "all" ? true : f.hourMode === "block" ? s.hr >= BLOCKS[f.block].h[0] && s.hr <= BLOCKS[f.block].h[1] : s.hr === f.hour;
  const passQ = (s) => f.q == null || s.q === f.q;
  const passPat = (s) => f.pat.every((p, j) => p == null || s.pat[j] === p);
  const passVol = (s) => f.vol == null || s.vol === f.vol;
  const passMag = (s) => f.mag == null || magBucket(s.prevAbs) === f.mag;
  const passDrift = (s) => !driftOn || (s.drift[f.lookN - 1] != null && Math.abs(s.drift[f.lookN - 1] - net) <= tolD);

  const ctx = useMemo(() => S.filter((s) => passDay(s) && passHour(s) && passQ(s) && passPat(s) && passVol(s) && passMag(s) && passDrift(s)), [f.days, f.hourMode, f.block, f.hour, f.q, f.pat, f.vol, f.mag, f.pxStart, f.pxNow, f.lookN, f.tolMode]);
  const matched = useMemo(() => (live ? ctx.filter((s) => Math.abs(s.d[f.minute - 1] - delta) <= tol) : ctx), [ctx, live, f.minute, delta, tol]);

  // ---- hero numbers ----
  const n = matched.length;
  const above = matched.filter((s) => s.f > 0).length;
  const below = matched.filter((s) => s.f < 0).length;
  const flat = n - above - below;
  const p = n ? above / n : null;
  const [lo, hi] = n ? wilson(above, n) : [null, null];
  const basP = S.filter((s) => s.f > 0).length / S.length;
  const ctxP = ctx.length ? ctx.filter((s) => s.f > 0).length / ctx.length : null;
  const medFinal = median(matched.map((s) => s.f));
  const drift = live ? median(matched.map((s) => s.f - delta)) : null;

  // ---- histogram ----
  const hist = useMemo(() => {
    const BW = 25, LIM = 250, nb = (LIM * 2) / BW;
    const bins = Array(nb).fill(0);
    matched.forEach((s) => {
      const v = Math.max(-LIM, Math.min(LIM - 0.01, s.f));
      bins[Math.floor((v + LIM) / BW)]++;
    });
    return { bins, max: Math.max(1, ...bins), BW, LIM };
  }, [matched]);

  // ---- hold matrix (context set) ----
  const holdMx = useMemo(
    () =>
      LEAD_BUCKETS.map((b) =>
        CHECKPOINTS.map((m) => {
          let held = 0, tot = 0;
          ctx.forEach((s) => {
            const l = s.d[m - 1], a = Math.abs(l);
            if (a >= b.lo && a < b.hi && s.f !== 0) {
              tot++;
              if ((l > 0) === (s.f > 0)) held++;
            }
          });
          return { p: tot ? held / tot : null, n: tot };
        })
      ),
    [ctx]
  );

  // ---- momentum (ignores pattern filter so it doesn't fight it) ----
  const mom = useMemo(() => {
    const set = S.filter((s) => passDay(s) && passHour(s) && passQ(s) && passVol(s) && passMag(s));
    const row = (test) => {
      const hit = set.filter(test);
      const u = hit.filter((s) => s.f > 0).length;
      return { p: hit.length ? u / hit.length : null, n: hit.length };
    };
    const streak = (dir, len) => row((s) => {
      for (let j = 0; j < len; j++) if (s.pat[4 - j] !== dir) return false;
      return len === 5 || s.pat[4 - len] !== dir || len === 4;
    });
    return {
      afterU: row((s) => s.pat[4] === "U"), afterD: row((s) => s.pat[4] === "D"),
      u2: streak("U", 2), u3: streak("U", 3), u4: streak("U", 4),
      d2: streak("D", 2), d3: streak("D", 3), d4: streak("D", 4),
    };
  }, [f.days, f.hourMode, f.block, f.hour, f.q, f.vol, f.mag]);

  // ---- texture (context set) ----
  const tex = useMemo(() => {
    const g = ctx;
    const l12 = g.filter((s) => s.d[11] !== 0 && s.f !== 0);
    const l14 = g.filter((s) => s.d[13] !== 0 && s.f !== 0);
    return {
      rng: mean(g.map((s) => s.rng)), medMove: median(g.map((s) => Math.abs(s.f))),
      aMR: mean(g.map((s) => s.aMR)), lMR: mean(g.map((s) => s.lMR)),
      flips: mean(g.map((s) => s.flips)),
      flip12: l12.length ? l12.filter((s) => (s.d[11] > 0) !== (s.f > 0)).length / l12.length : null,
      flip14: l14.length ? l14.filter((s) => (s.d[13] > 0) !== (s.f > 0)).length / l14.length : null,
      n12: l12.length, n14: l14.length,
    };
  }, [ctx]);

  // ---- hour heatmap (day filter only) ----
  const heat = useMemo(() => {
    const set = S.filter(passDay);
    return Array.from({ length: 24 }, (_, h) => {
      const g = set.filter((s) => s.hr === h);
      const u = g.filter((s) => s.f > 0).length;
      return { p: g.length ? u / g.length : null, n: g.length };
    });
  }, [f.days]);

  // ---- quarter split (ctx ignoring q) ----
  const qsplit = useMemo(() => {
    const set = S.filter((s) => passDay(s) && passHour(s) && passPat(s) && passVol(s) && passMag(s) && passDrift(s));
    return [0, 1, 2, 3].map((q) => {
      const g = set.filter((s) => s.q === q);
      return { p: g.length ? g.filter((s) => s.f > 0).length / g.length : null, n: g.length };
    });
  }, [f.days, f.hourMode, f.block, f.hour, f.pat, f.vol, f.mag, f.pxStart, f.pxNow, f.lookN, f.tolMode]);

  // ---- active condition chips ----
  const conds = [];
  if (f.days.length) conds.push({ k: "days", l: f.days.map((d) => DOWS[d]).join(" ") , clear: () => up({ days: [] }) });
  if (f.hourMode === "block") conds.push({ k: "hr", l: BLOCKS[f.block].l + " CT", clear: () => up({ hourMode: "all" }) });
  if (f.hourMode === "hour") conds.push({ k: "hr", l: hourLabel(f.hour) + " CT", clear: () => up({ hourMode: "all" }) });
  if (f.q != null) conds.push({ k: "q", l: ":" + ["00", "15", "30", "45"][f.q], clear: () => up({ q: null }) });
  if (f.pat.some((x) => x)) conds.push({ k: "pat", l: "last " + f.pat.map((x) => x || "·").join(""), clear: () => up({ pat: [...FRESH.pat] }) });
  if (driftOn) conds.push({ k: "drift", l: `net ${fmt$(net, true)} over ${f.lookN}s ±$${Math.round(tolD)}`, clear: () => up({ pxStart: "", pxNow: "" }) });
  if (f.vol) conds.push({ k: "vol", l: { L: "low vol", M: "mid vol", H: "high vol" }[f.vol], clear: () => up({ vol: null }) });
  if (f.mag) conds.push({ k: "mag", l: { S: "prior small", M: "prior mid", B: "prior big" }[f.mag], clear: () => up({ mag: null }) });
  if (live) conds.push({ k: "live", l: `min ${f.minute} · ${fmt$(delta, true)} ±${Math.round(tol)}`, clear: () => up({ magIn: "" }) });

  const toggleFollow = () => up(f.follow ? { follow: false } : { follow: true, minute: ct.mis });
  const dhActive = f.days.length === 1 && f.days[0] === ct.dow && f.hourMode === "hour" && f.hour === ct.hr;
  const toggleDayHr = () => up(dhActive ? { days: [], hourMode: "all" } : { days: [ct.dow], hourMode: "hour", hour: ct.hr });

  const dep = matched.length / S.length;

  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-200 font-mono">
      <div className="max-w-2xl mx-auto px-3 py-4 space-y-3">

        {/* ---- session clock ---- */}
        <div className="border border-zinc-800 rounded-lg bg-zinc-900/60 px-3.5 py-3">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] uppercase tracking-widest text-zinc-500">BTC · 15m session edge</div>
              <div className="text-lg text-zinc-100 tabular-nums leading-tight mt-0.5">
                {ct.clock} <span className="text-zinc-500 text-sm">CT · {DOWS[ct.dow]}</span>
              </div>
            </div>
            <div className="text-right">
              <div className="text-[10px] text-zinc-500">session {ct.window}</div>
              <div className={`text-lg tabular-nums leading-tight ${ct.secLeft <= 60 ? "text-amber-400" : "text-zinc-100"}`}>
                {Math.floor(ct.secLeft / 60)}:{String(ct.secLeft % 60).padStart(2, "0")}
                <span className="text-zinc-500 text-sm"> to close</span>
              </div>
            </div>
          </div>
          <div className="flex gap-1 mt-2.5">
            {Array.from({ length: 15 }, (_, k) => (
              <div key={k} className={`h-1 flex-1 rounded-sm ${k < ct.mis ? "bg-zinc-400" : k === ct.mis ? "bg-amber-400 animate-pulse" : "bg-zinc-800"}`} />
            ))}
          </div>
          <div className="flex items-center justify-between mt-2.5">
            <div className="text-[10px] text-zinc-600">minute {ct.mis} of 15</div>
            <div className="flex gap-2">
              <button onClick={toggleFollow} className={`text-[11px] px-2.5 py-1 rounded-md border ${f.follow ? "border-amber-400 bg-amber-500/15 text-amber-300" : "border-amber-500/50 text-amber-400 hover:bg-amber-500/10"}`}>
                {f.follow ? "following clock ●" : "follow clock"}
              </button>
              <button onClick={toggleDayHr} className={`text-[11px] px-2.5 py-1 rounded-md border ${dhActive ? "border-zinc-100 bg-zinc-100 text-zinc-900" : "border-zinc-700 text-zinc-400 hover:border-zinc-500"}`}>
                today + hr
              </button>
              <button onClick={() => setF({ ...FRESH, pat: [...FRESH.pat] })} className="text-[11px] px-2.5 py-1 rounded-md border border-zinc-700 text-zinc-400 hover:border-zinc-500">
                reset
              </button>
            </div>
          </div>
        </div>

        {/* ---- the dial ---- */}
        <Card>
          <Eyebrow right={`baseline ${fmtP(basP)}${ctxP != null && conds.length ? ` · context ${fmtP(ctxP)}` : ""}`}>
            closes above open
          </Eyebrow>
          <div className="flex items-end gap-4">
            <div className={`text-7xl leading-none tabular-nums ${p == null ? "text-zinc-600" : p >= 0.5 ? "text-emerald-400" : "text-red-400"}`}>
              {p == null ? "—" : Math.round(p * 100)}
              <span className="text-3xl text-zinc-500">%</span>
            </div>
            <div className="pb-1 text-[11px] leading-relaxed text-zinc-500">
              <div>
                <span className={nTone(n)}>n = {n}</span> of {S.length}
              </div>
              <div>90% CI {p == null ? "—" : `${Math.round(lo * 100)}–${Math.round(hi * 100)}%`}</div>
              <div>
                below {fmtP(n ? below / n : null)}
                {flat ? ` · flat ${flat}` : ""}
              </div>
            </div>
          </div>

          {/* CI bar */}
          <div className="relative h-1.5 mt-3 rounded bg-zinc-800">
            <div className="absolute inset-y-0 w-px bg-zinc-600" style={{ left: "50%" }} />
            {p != null && (
              <>
                <div className="absolute inset-y-0 rounded bg-zinc-600/60" style={{ left: `${lo * 100}%`, width: `${(hi - lo) * 100}%` }} />
                <div className={`absolute -top-0.5 h-2.5 w-0.5 rounded ${p >= 0.5 ? "bg-emerald-400" : "bg-red-400"}`} style={{ left: `${p * 100}%` }} />
              </>
            )}
          </div>

          {/* histogram of finals */}
          <div className="mt-4">
            <div className="flex items-end gap-px h-14">
              {hist.bins.map((b, i) => {
                const mid = -hist.LIM + hist.BW * i + hist.BW / 2;
                return (
                  <div key={i} className="flex-1 flex flex-col justify-end" title={`${mid < 0 ? "−" : "+"}$${Math.abs(mid - hist.BW / 2)}–$${Math.abs(mid + hist.BW / 2)}: ${b}`}>
                    <div className={`w-full rounded-sm ${mid > 0 ? "bg-emerald-500/70" : "bg-red-500/60"}`} style={{ height: `${(b / hist.max) * 100}%`, minHeight: b ? 2 : 0 }} />
                  </div>
                );
              })}
            </div>
            <div className="relative flex justify-between text-[9px] text-zinc-600 mt-1">
              <span>−$250</span><span>open</span><span>+$250</span>
              {live && (
                <div className="absolute -top-16 h-16 w-px bg-amber-400/80" style={{ left: `${((Math.max(-250, Math.min(250, delta)) + 250) / 500) * 100}%` }}>
                  <div className="absolute -top-1 -translate-x-1/2 text-amber-400 text-[9px] whitespace-nowrap">now {fmt$(delta, true)}</div>
                </div>
              )}
            </div>
            <div className="text-[10px] text-zinc-600 mt-2">
              final move: median {fmt$(medFinal, true)}
              {live && drift != null ? ` · median drift from here ${fmt$(drift, true)}` : ""}
            </div>
          </div>

          {n < 30 && <div className="mt-3 text-[11px] text-red-400/90">thin sample — this is noise, not signal. Remove a condition or widen tolerance.</div>}
        </Card>

        {/* ---- evidence rail ---- */}
        <Card>
          <Eyebrow right={`${Math.round(dep * 100)}% of data in play`}>evidence rail</Eyebrow>
          <div className="h-1 rounded bg-zinc-800 mb-2.5">
            <div className={`h-1 rounded ${n >= 100 ? "bg-zinc-400" : n >= 30 ? "bg-amber-400" : "bg-red-400"}`} style={{ width: `${Math.max(1, dep * 100)}%` }} />
          </div>
          {conds.length ? (
            <div className="flex flex-wrap gap-1.5">
              {conds.map((c) => (
                <button key={c.k + c.l} onClick={c.clear} className="px-2 py-1 rounded-md bg-zinc-800/80 border border-zinc-700 text-[11px] text-zinc-300 hover:border-red-500/50 hover:text-red-300">
                  {c.l} <span className="text-zinc-500">✕</span>
                </button>
              ))}
            </div>
          ) : (
            <div className="text-[11px] text-zinc-600">no conditions — showing all {S.length} sessions. Every input below narrows the evidence; the bar shows what survives.</div>
          )}
        </Card>

        {/* ---- live state ---- */}
        <Card className="border-zinc-700">
          <Eyebrow right={live ? `matching ±$${Math.round(tol)}` : "needs minute + distance"}>live session state — inputs</Eyebrow>
          <div className="text-[11px] text-zinc-500 mb-1.5">
            minutes into session: <span className={f.follow ? "text-amber-300" : "text-zinc-200"}>{f.minute || "off"}{f.follow ? " · live" : ""}</span>
          </div>
          <input
            type="range" min="0" max="14" value={f.minute}
            onChange={(e) => up({ minute: +e.target.value, follow: false })}
            className="w-full accent-amber-400"
          />
          <div className="flex justify-between text-[9px] text-zinc-600 -mt-1 mb-3"><span>off</span><span>7</span><span>14</span></div>

          <div className="text-[11px] text-zinc-500 mb-1.5">price now vs session open</div>
          <div className="flex gap-1.5">
            <button
              onClick={() => up({ sign: f.sign * -1 })}
              className={`px-3 rounded-md border text-sm ${f.sign > 0 ? "border-emerald-500/60 text-emerald-400 bg-emerald-500/10" : "border-red-500/60 text-red-400 bg-red-500/10"}`}
            >
              {f.sign > 0 ? "above" : "below"}
            </button>
            <div className="flex items-center flex-1 bg-zinc-950 border border-zinc-700 rounded-md px-2.5 focus-within:border-amber-500/60">
              <span className="text-zinc-500 text-sm">$</span>
              <input
                inputMode="decimal" placeholder="0" value={f.magIn}
                onChange={(e) => up({ magIn: e.target.value.replace(/[^0-9.]/g, "") })}
                className="w-full bg-transparent outline-none py-2 px-1 text-zinc-100 tabular-nums text-sm"
              />
            </div>
            {[5, 25].map((v) => (
              <button key={v} onClick={() => up({ magIn: String(Math.max(0, (Math.abs(+f.magIn) || 0) + v)) })} className="px-2.5 rounded-md border border-zinc-700 text-zinc-400 text-xs hover:border-zinc-500">
                +{v}
              </button>
            ))}
          </div>
          <div className="flex gap-1.5 mt-2.5 items-center">
            <span className="text-[10px] text-zinc-600 mr-1">match band</span>
            {["tight", "auto", "wide"].map((m) => (
              <Chip key={m} on={f.tolMode === m} onClick={() => up({ tolMode: m })}>{m}</Chip>
            ))}
          </div>
        </Card>

        {/* ---- conditions ---- */}
        <Card>
          <Eyebrow>conditions — every one optional</Eyebrow>

          <div className="text-[10px] text-zinc-600 mb-1.5">day (CT)</div>
          <div className="flex flex-wrap gap-1.5 mb-3.5">
            {DOWS.map((d, i) => (
              <Chip key={d} on={f.days.includes(i)} onClick={() => up({ days: f.days.includes(i) ? f.days.filter((x) => x !== i) : [...f.days, i] })}>{d}</Chip>
            ))}
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">time of day (CT)</div>
          <div className="flex flex-wrap gap-1.5 mb-2">
            <Chip on={f.hourMode === "all"} onClick={() => up({ hourMode: "all" })}>any</Chip>
            {BLOCKS.map((b, i) => (
              <Chip key={b.l} on={f.hourMode === "block" && f.block === i} onClick={() => up({ hourMode: "block", block: i })}>{b.l}</Chip>
            ))}
          </div>
          <div className="flex items-center gap-2 mb-3.5">
            <span className="text-[10px] text-zinc-600">or exact hour</span>
            <select
              value={f.hourMode === "hour" ? f.hour : ""}
              onChange={(e) => e.target.value === "" ? up({ hourMode: "all" }) : up({ hourMode: "hour", hour: +e.target.value })}
              className="bg-zinc-950 border border-zinc-700 rounded-md text-xs text-zinc-300 px-2 py-1.5 outline-none"
            >
              <option value="">—</option>
              {Array.from({ length: 24 }, (_, h) => (
                <option key={h} value={h}>{hourLabel(h)}</option>
              ))}
            </select>
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">quarter within the hour</div>
          <div className="flex gap-1.5 mb-3.5">
            <Chip on={f.q == null} onClick={() => up({ q: null })}>any</Chip>
            {[":00", ":15", ":30", ":45"].map((l, i) => (
              <Chip key={l} on={f.q === i} onClick={() => up({ q: f.q === i ? null : i })}>{l}</Chip>
            ))}
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">last 5 sessions — tap to cycle · / U / D (rightmost = most recent)</div>
          <div className="flex gap-1.5 mb-3.5">
            {f.pat.map((v, j) => (
              <Chip
                key={j} on={v != null} tone={v}
                onClick={() => {
                  const nx = [...f.pat];
                  nx[j] = v == null ? "U" : v === "U" ? "D" : null;
                  up({ pat: nx });
                }}
              >
                {v || "·"}
              </Chip>
            ))}
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">recent drift — open price N sessions back vs this session's open</div>
          <div className="flex gap-1.5 mb-2">
            <span className="text-[10px] text-zinc-600 self-center">over last</span>
            {[1, 2, 3, 4, 5].map((N) => (
              <Chip key={N} on={f.lookN === N} onClick={() => up({ lookN: N })}>{N}</Chip>
            ))}
            <span className="text-[10px] text-zinc-600 self-center">sessions</span>
          </div>
          <div className="flex gap-1.5 mb-1.5">
            <div className="flex items-center flex-1 bg-zinc-950 border border-zinc-700 rounded-md px-2.5 focus-within:border-amber-500/60">
              <span className="text-zinc-500 text-[10px] whitespace-nowrap pr-1">open {f.lookN} back $</span>
              <input
                inputMode="decimal" placeholder="—" value={f.pxStart}
                onChange={(e) => up({ pxStart: e.target.value.replace(/[^0-9.]/g, "") })}
                className="w-full bg-transparent outline-none py-2 text-zinc-100 tabular-nums text-sm"
              />
            </div>
            <div className="flex items-center flex-1 bg-zinc-950 border border-zinc-700 rounded-md px-2.5 focus-within:border-amber-500/60">
              <span className="text-zinc-500 text-[10px] whitespace-nowrap pr-1">this open $</span>
              <input
                inputMode="decimal" placeholder="—" value={f.pxNow}
                onChange={(e) => up({ pxNow: e.target.value.replace(/[^0-9.]/g, "") })}
                className="w-full bg-transparent outline-none py-2 text-zinc-100 tabular-nums text-sm"
              />
            </div>
          </div>
          <div className="text-[10px] mb-3.5">
            {driftOn ? (
              <span className={net > 0 ? "text-emerald-400" : net < 0 ? "text-red-400" : "text-zinc-400"}>
                net {fmt$(net, true)} over {f.lookN} session{f.lookN > 1 ? "s" : ""} ({f.lookN * 15} min) — matching ±${Math.round(tolD)}
              </span>
            ) : (
              <span className="text-zinc-600">fill both prices to condition on trend magnitude, not just U/D direction</span>
            )}
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">volatility regime — trailing 2h avg session range (low &lt; ${META.volT[0]} · high &gt; ${META.volT[1]})</div>
          <div className="flex gap-1.5 mb-3.5">
            <Chip on={f.vol == null} onClick={() => up({ vol: null })}>any</Chip>
            {["L", "M", "H"].map((v) => (
              <Chip key={v} on={f.vol === v} onClick={() => up({ vol: f.vol === v ? null : v })}>{{ L: "low", M: "mid", H: "high" }[v]}</Chip>
            ))}
          </div>

          <div className="text-[10px] text-zinc-600 mb-1.5">prior session move size (small &lt; ${META.magT[0]} · big &gt; ${META.magT[1]})</div>
          <div className="flex gap-1.5">
            <Chip on={f.mag == null} onClick={() => up({ mag: null })}>any</Chip>
            {["S", "M", "B"].map((v) => (
              <Chip key={v} on={f.mag === v} onClick={() => up({ mag: f.mag === v ? null : v })}>{{ S: "small", M: "mid", B: "big" }[v]}</Chip>
            ))}
          </div>
        </Card>

        {/* ---- hold matrix ---- */}
        <Card>
          <Eyebrow right={`context n = ${ctx.length}`}>lead holds to close — % by lead size × minute</Eyebrow>
          <div className="grid gap-y-1" style={{ gridTemplateColumns: "3.6rem repeat(5, 1fr)" }}>
            <div />
            {CHECKPOINTS.map((m) => (
              <div key={m} className="text-[10px] text-zinc-600 text-center">:{String(m).padStart(2, "0")}</div>
            ))}
            {LEAD_BUCKETS.map((b, bi) => (
              <Fragment key={b.l}>
                <div className="text-[10px] text-zinc-500 self-center">{b.l}</div>
                {holdMx[bi].map((c, ci) => (
                  <button
                    key={ci}
                    onClick={() => up({ minute: CHECKPOINTS[ci], sign: 1, magIn: String(Math.round((b.lo + Math.min(b.hi, 150)) / 2)) })}
                    title={`n = ${c.n} — tap to load scenario`}
                    className={`text-center text-sm tabular-nums py-1 rounded hover:bg-zinc-800/70 ${holdTone(c.p)} ${c.n < 30 ? "opacity-50" : ""}`}
                  >
                    {c.p == null ? "·" : Math.round(c.p * 100)}
                  </button>
                ))}
              </Fragment>
            ))}
          </div>
          <div className="text-[10px] text-zinc-600 mt-2">read: a $25–50 lead at minute :10 held to the close X% of the time. Dimmed = n &lt; 30. Tap any cell to load it as your live scenario.</div>
        </Card>

        {/* ---- momentum + quarters ---- */}
        <div className="grid grid-cols-2 gap-3">
          <Card>
            <Eyebrow>momentum</Eyebrow>
            {[
              ["after up", mom.afterU], ["after down", mom.afterD],
              ["after U·U", mom.u2], ["after D·D", mom.d2],
              ["after U·U·U", mom.u3], ["after D·D·D", mom.d3],
              ["after 4 up", mom.u4], ["after 4 down", mom.d4],
            ].map(([l, r]) => (
              <div key={l} className="flex justify-between text-xs py-0.5">
                <span className="text-zinc-500">{l}</span>
                <span className="tabular-nums">
                  <span className={r.p == null ? "text-zinc-600" : r.p >= 0.5 ? "text-emerald-400" : "text-red-400"}>{fmtP(r.p)}</span>
                  <span className={`ml-1.5 text-[10px] ${nTone(r.n)}`}>{r.n}</span>
                </span>
              </div>
            ))}
            <div className="text-[9px] text-zinc-600 mt-1.5">% next closes up · n</div>
          </Card>
          <Card>
            <Eyebrow>quarter of hour</Eyebrow>
            {qsplit.map((r, i) => (
              <div key={i} className="flex justify-between text-xs py-0.5">
                <span className="text-zinc-500">{[":00", ":15", ":30", ":45"][i]} session</span>
                <span className="tabular-nums">
                  <span className={r.p == null ? "text-zinc-600" : r.p >= 0.5 ? "text-emerald-400" : "text-red-400"}>{fmtP(r.p)}</span>
                  <span className={`ml-1.5 text-[10px] ${nTone(r.n)}`}>{r.n}</span>
                </span>
              </div>
            ))}
            <div className="text-[9px] text-zinc-600 mt-1.5">% closes up · n</div>
            <div className="border-t border-zinc-800 mt-2 pt-2 space-y-1 text-xs">
              <div className="flex justify-between"><span className="text-zinc-500">leader at :12 lost</span><span className="tabular-nums text-zinc-200">{fmtP(tex.flip12)}</span></div>
              <div className="flex justify-between"><span className="text-zinc-500">leader at :14 lost</span><span className="tabular-nums text-zinc-200">{fmtP(tex.flip14)}</span></div>
            </div>
          </Card>
        </div>

        {/* ---- texture ---- */}
        <Card>
          <Eyebrow right={`context n = ${ctx.length}`}>session texture</Eyebrow>
          <div className="grid grid-cols-3 gap-y-2.5 text-center">
            {[
              ["avg range", fmt$(tex.rng)], ["median |move|", fmt$(tex.medMove)], ["avg flips / session", tex.flips == null ? "—" : tex.flips.toFixed(1)],
              ["avg 1-min swing", fmt$(tex.aMR)], ["final-min swing", fmt$(tex.lMR)], ["vol regime cutoffs", `$${META.volT[0]} / $${META.volT[1]}`],
            ].map(([l, v]) => (
              <div key={l}>
                <div className="text-base tabular-nums text-zinc-100">{v}</div>
                <div className="text-[9px] text-zinc-600 mt-0.5">{l}</div>
              </div>
            ))}
          </div>
        </Card>

        {/* ---- hour heatmap ---- */}
        <Card>
          <Eyebrow right={f.days.length ? f.days.map((d) => DOWS[d]).join(" ") : "all days"}>up-rate by hour (CT) — tap to filter</Eyebrow>
          <div className="grid grid-cols-12 gap-1">
            {heat.map((c, h) => {
              const dev = c.p == null ? 0 : c.p - 0.5;
              return (
                <button
                  key={h}
                  onClick={() => up({ hourMode: "hour", hour: h })}
                  title={`${hourLabel(h)} — up ${fmtP(c.p)} · n = ${c.n}`}
                  className={`rounded-sm py-1.5 text-[9px] tabular-nums border ${f.hourMode === "hour" && f.hour === h ? "border-amber-400" : "border-transparent"}`}
                  style={{ backgroundColor: dev >= 0 ? `rgba(16,185,129,${Math.min(0.75, dev * 5)})` : `rgba(239,68,68,${Math.min(0.75, -dev * 5)})`, color: "#d4d4d8" }}
                >
                  {hourLabel(h)}
                </button>
              );
            })}
          </div>
          <div className="text-[9px] text-zinc-600 mt-2">green = closed up more often than not · red = down · intensity = how far from 50/50</div>
        </Card>

        <div className="text-[10px] leading-relaxed text-zinc-600 px-1 pb-6">
          Bitstamp BTCUSD 1-min · Jul 8 – Aug 4 2026 · {S.length} sessions · all times CT. Sessions run :00/:15/:30/:45; open = first-minute open, close = last-minute close. These are historical frequencies, not predictions — thin slices are noise, so trust the interval and the n, not the point estimate. Edge only exists where these numbers beat the market's implied price after fees.
        </div>
      </div>
    </div>
  );
}
